test("#9 SIGNED_ZERO_SCALARS_EXACT_PASS", () => {
  const angle0 = meleeAtan2(0, 1);
  assertEquals(angle0, 0);
  assertEquals(1 / angle0 < 0, false);
  assertEquals(meleeCos(angle0), 1);
  assertEquals(meleeSin(angle0), 0);
  assertEquals(1 / meleeSin(angle0) < 0, false);
  const angle6 = meleeAtan2(-0.0, 1);
  assertEquals(angle6, 0);
  assertEquals(1 / angle6 < 0, true);
  assertEquals(meleeCos(angle6), 1);
  assertEquals(meleeSin(angle6), 0);
  assertEquals(1 / meleeSin(angle6) < 0, false);
  const angle12 = meleeAtan2(0, -1);
  assertEquals(angle12, 3.1415927410125732);
  assertEquals(meleeCos(angle12), -1);
  assertEquals(meleeSin(angle12), -8.742277657347586e-8);
  const angle16 = meleeAtan2(-0.0, -1);
  assertEquals(angle16, -3.1415927410125732);
  assertEquals(meleeCos(angle16), -1);
  assertEquals(meleeSin(angle16), 8.742277657347586e-8);
  const angle20 = meleeAtan2(1, 0);
  assertEquals(angle20, 1.5707963705062866);
  assertEquals(meleeCos(angle20), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle20), 1);
  const angle24 = meleeAtan2(1, -0.0);
  assertEquals(angle24, 1.5707963705062866);
  assertEquals(meleeCos(angle24), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle24), 1);
  const angle28 = meleeAtan2(-1, 0);
  assertEquals(angle28, -1.5707963705062866);
  assertEquals(meleeCos(angle28), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle28), -1);
  const angle32 = meleeAtan2(-1, -0.0);
  assertEquals(angle32, -1.5707963705062866);
  assertEquals(meleeCos(angle32), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle32), -1);
  const angle36 = meleeAtan2(0, 0);
  assertEquals(angle36, 1.5707963705062866);
  assertEquals(meleeCos(angle36), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle36), 1);
  const angle40 = meleeAtan2(-0.0, 0);
  assertEquals(angle40, -1.5707963705062866);
  assertEquals(meleeCos(angle40), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle40), -1);
  const angle44 = meleeAtan2(0, -0.0);
  assertEquals(angle44, 1.5707963705062866);
  assertEquals(meleeCos(angle44), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle44), 1);
  const angle48 = meleeAtan2(-0.0, -0.0);
  assertEquals(angle48, -1.5707963705062866);
  assertEquals(meleeCos(angle48), -5.5655068109672357e-8);
  assertEquals(meleeSin(angle48), -1);
  assertEquals(meleeCos(0), 1);
  assertEquals(meleeSin(0), 0);
  assertEquals(1 / meleeSin(0) < 0, false);
  assertEquals(meleeCos(-0.0), 1);
  assertEquals(meleeSin(-0.0), 0);
  assertEquals(1 / meleeSin(-0.0) < 0, false);
});

